import type { Campaign, Entity, EntityDraft, Relationship, RelationshipDraft } from './types'

const DATABASE_KEY = 'campaign-compass-sqlite-v1'
const now = () => new Date().toISOString()
let database: Database

const schema = `
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS campaigns (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entities (id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('character','faction')), name TEXT NOT NULL, short_description TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('friendly','neutral','enemy')), favorite INTEGER NOT NULL DEFAULT 0, affiliation TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT '', activity TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tags (id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE, name TEXT NOT NULL COLLATE NOCASE, UNIQUE(campaign_id, name));
CREATE TABLE IF NOT EXISTS entity_tags (entity_id TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(entity_id, tag_id));
CREATE TABLE IF NOT EXISTS relationships (id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE, entity_a_id TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE, entity_b_id TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE, type TEXT NOT NULL, short_description TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', importance INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(entity_a_id <> entity_b_id));
CREATE TABLE IF NOT EXISTS reference_imports (campaign_id TEXT NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE, import_key TEXT NOT NULL, PRIMARY KEY(campaign_id, import_key));
CREATE INDEX IF NOT EXISTS idx_entities_campaign ON entities(campaign_id); CREATE INDEX IF NOT EXISTS idx_relationships_campaign ON relationships(campaign_id);`

